CREATE TABLE `electricity_bill_info` (
  `Sr_no` varchar(145) NOT NULL,
  `Consumer_Number` varchar(145) DEFAULT NULL,
  `Name` varchar(145) DEFAULT NULL,
  `Address` varchar(145) DEFAULT NULL,
  `BU` varchar(145) DEFAULT NULL,
  `Connection_Type` varchar(145) DEFAULT NULL,
  `Bill_Month` varchar(145) DEFAULT NULL,
  `Consumption_Units` varchar(145) DEFAULT NULL,
  `status` varchar(145) DEFAULT NULL,
  `Bill_Amount` varchar(145) DEFAULT NULL,
  `Paid_Amount` varchar(145) DEFAULT NULL,
  `Payment_Date` varchar(145) DEFAULT NULL,
  PRIMARY KEY (`Sr_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
